INSERT INTO `plo` (`degree_id`,`code`,`description`) VALUES
(15,'PLO 1','Develop pedagogical approaches that facilitate learning using a wide range of teaching methodologies that are learner-centered, innovative, inclusive and developmentally appropriate for young learners.'),
(15,'PLO 10','Generate ideas with resourcefulness, originality, and insight in the development and utilization of Information communication technology in promoting quality, relevant and sustainable educational practices appropriate to early childhood learners.'),
(15,'PLO 2','Design and implement tools that employ thinking skills in planning, monitoring, assessing, and reporting learning processes and outcomes.'),
(15,'PLO 3','Appraise one’s own beliefs and thinking of education in the contexts of philosophy, society, culture and cultural diversity, inclusivity, history, psychology and politics.'),
(15,'PLO 4','Pursue lifelong learning for personal and professional growth through varied experiential and field-based opportunities.'),
(15,'PLO 5','Effectively communicate orally and in writing using varied forms of media.'),
(15,'PLO 6','Illustrate collaborative skills by working effectively and independently in multi-disciplinary and multi-cultural teams.'),
(15,'PLO 7','Develop and integrate Christian leadership skills by practicing professional and ethical teaching standards sensitive to the changing local, national, and global realities.'),
(15,'PLO 8','Support and advocate for children’s rights, equity, diversity, community, patriotism, environmental concerns and democratic ideals in a global context as well as preserve and promote Filipino historical and cultural heritage.'),
(15,'PLO 9','Develop innovative curricula, instructional plans, teaching approaches, and resources for diverse early childhood learners.'),
(30,'PLO 1','Display mastery of the methods, theories, and empirical studies in the field of Biology/Chemistry/Physics/ Mathematics Education.'),
(30,'PLO 10','Critically examine one’s subscription to relevant Lasallian values in the transformation of educational practices for the common good.'),
(30,'PLO 11','Practice the values and principles aligned with the Lasallian virtues of prudence, wisdom, and gentleness in considering the welfare of all learners.'),
(30,'PLO 12','Develop innovative and relevant teaching-learning materials that will integrate technology for 21st century STEM learners in a variety of settings.'),
(30,'PLO 13','Show competence and creativity in infusing appropriate technology in teaching Biology/ Chemistry/ Physics/ Mathematics at the Basic Education and Higher Education levels.'),
(30,'PLO 2','Develop and validate an innovative and culturally-sensitive assessment instrument that measures a relevant science/mathematics teaching/learning construct accurately.'),
(30,'PLO 3','Conduct independent and original dissertation research in the field of Biology/Chemistry/Physics/ Mathematics Education.'),
(30,'PLO 4','Communicate educational research to both science /mathematics education researchers and practitioners through research publication and/or presentation.'),
(30,'PLO 5','Manage a research study or project in the field of Biology/Chemistry/ Physics/Mathematics Education.'),
(30,'PLO 6','Apply educational research methodologies and appropriate technologies to solve current educational issues and problems in Biology/Chemistry/Physics/ Mathematics Education.'),
(30,'PLO 7','Practice self-care and positivity in appreciating difficulties encountered as a Science/ Math educator.'),
(30,'PLO 8','Demonstrate knowledge and understanding of ethical standards in executing educational research in Biology/Chemistry/ Physics/Mathematics Education.'),
(30,'PLO 9','Design and manage a service learning project for Science and Mathematics teachers in the Basic Education level.'),
