INSERT INTO `plo` (`degree_id`,`code`,`description`) VALUES
(315,'PLO 1','Graduates will demonstrate a comprehensive understanding and application of essential business skills across functional areas (e.g., accounting, analytics and information technology, commercial law, finance, human resources, and/or marketing)'),
(315,'PLO 2','Graduates will exhibit a strong commitment to ethical decision-making and/or adherence to legal or regulatory requirements in business contexts, recognizing their responsibility to stakeholders and society at large.'),
(315,'PLO 3','Graduates will exemplify the principles of Lasallian business leadership, emphasizing humanistic values, social responsibility, and sustainable practices to promote the common good for all.'),
